/**
 * northtrail-post.data.js — GENERATED. The @northtrail post photograph.
 *
 * The film's post frame shows a REAL product photograph, not drawn art. The
 * picture is inlined as a data URI rather than fetched: a renderer that walks
 * the timeline frame by frame gets no second chance at a pending load, and a
 * relative src would resolve differently from the shared stage and from a
 * snapshot dir. Same discipline saru-mark-tile uses for the monkey mark.
 *
 * Source frame is 4:5 (720x900 here, archived at 1080x1350 beside this file as
 * northtrail-post.jpg); the post window is square and covers, so the crop is
 * driven from the preset with objectPosition.
 *
 * GROUND is the picture's dominant colour — painted under the image so a frame
 * can never open on white if a decode has not landed.
 */
export const NORTHTRAIL_POST_GROUND = "#3e3e30";
export const NORTHTRAIL_POST = "data:image/jpeg;base64,";
export default NORTHTRAIL_POST;
